import{_ as l,o as i,c as e,O as t}from"./chunks/framework.ac0f74f3.js";const r="/assets/bj1.dc5dd400.png",p="/assets/bj2.861733ec.png",o="/assets/bj3.22e2a60f.png",h="/assets/bj7.9160c117.png",s="/assets/bj4.44689a8b.png",n="/assets/bj5.b1f02d3b.png",u="/assets/bj6.a8140578.png",x=JSON.parse('{"title":"部件列表","description":"","frontmatter":{},"headers":[],"relativePath":"技术管理/部件列表.md","filePath":"技术管理/部件列表.md"}'),d={name:"技术管理/部件列表.md"};function c(_,a,b,m,q,f){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="部件列表" tabindex="-1">部件列表 <a class="header-anchor" href="#部件列表" aria-label="Permalink to &quot;部件列表&quot;">​</a></h1><blockquote><p>部件列表位于技术管理板块，可添加部件系列，在系列中新增部件，新增的部件支持维护路线，复制，编辑，删除 等操作.</p></blockquote><h4 id="_1-新增-编辑部件系列" tabindex="-1">1.新增/编辑部件系列 <a class="header-anchor" href="#_1-新增-编辑部件系列" aria-label="Permalink to &quot;1.新增/编辑部件系列&quot;">​</a></h4><ul><li><p>默认显示所有系列，系列上面可点击＋新增系列</p><p>-新增的系列可再加子系列，子系列也可以往下面延申</p><p>-如果该系列下有部件数据，就无法删除，没有数据的 可删除</p><p>-点击编辑图标可更改名称或点击调整图标可调换系列位置</p><p>-分类树支持拖拽调整宽度</p></li></ul><h4 id="_2-新增部件" tabindex="-1">2.新增部件 <a class="header-anchor" href="#_2-新增部件" aria-label="Permalink to &quot;2.新增部件&quot;">​</a></h4><ul><li><p>点击新增部件按钮添加部件</p><p>-在新增部件之前需选择对应的系列（放置的位置）</p><p>-新增的部件名称/规格可以重复</p><p>-如果在创建部件时状态选择了停用，那这个部件就不可用</p></li></ul><h4 id="_3-表头设置" tabindex="-1">3.表头设置 <a class="header-anchor" href="#_3-表头设置" aria-label="Permalink to &quot;3.表头设置&quot;">​</a></h4><ul><li>点击表头设置图标可更改表头字段的显示/隐藏</li></ul><p><img src="'+r+'" alt="如图所示"></p><h4 id="_4-复制功能" tabindex="-1">4.复制功能 <a class="header-anchor" href="#_4-复制功能" aria-label="Permalink to &quot;4.复制功能&quot;">​</a></h4><ul><li>可在这个部件的基础上去复制一个相同的部件出来，能够复制全部信息</li></ul><h4 id="_5-删除功能" tabindex="-1">5.删除功能 <a class="header-anchor" href="#_5-删除功能" aria-label="Permalink to &quot;5.删除功能&quot;">​</a></h4><ul><li><p>需要删除时先在编辑中将状态改为停用才能删除</p></li><li><p>有BOM的情况下是无法删除的，需要解除在进行删除</p></li></ul><h4 id="_6-批量删除" tabindex="-1">6.批量删除 <a class="header-anchor" href="#_6-批量删除" aria-label="Permalink to &quot;6.批量删除&quot;">​</a></h4><ul><li><p>勾选需要删除的内容，点击批量删除按钮即可删除</p><p>-需要删除时先在编辑中将状态改为停用才能删除</p><p>-有BOM的情况下是无法删除的，需要解除在进行删除</p></li></ul><h4 id="_7-编辑功能" tabindex="-1">7.编辑功能 <a class="header-anchor" href="#_7-编辑功能" aria-label="Permalink to &quot;7.编辑功能&quot;">​</a></h4><ul><li>可在原有新增的部件上进行编辑修改</li></ul><h4 id="_8-批量编辑" tabindex="-1">8.批量编辑 <a class="header-anchor" href="#_8-批量编辑" aria-label="Permalink to &quot;8.批量编辑&quot;">​</a></h4><ul><li><p>先勾选需要批量编辑的部件，点击批量编辑按钮即可进行编辑</p><p>-点击可维护检验准则（支持添加多个检验项目）</p></li></ul><p><img src="'+p+'" alt="如图所示"></p><h4 id="_9-图纸" tabindex="-1">9.图纸 <a class="header-anchor" href="#_9-图纸" aria-label="Permalink to &quot;9.图纸&quot;">​</a></h4><ul><li>点击可查看新增/编辑时选择上传的文件</li></ul><h4 id="_10-维护检验准则" tabindex="-1">10.维护检验准则 <a class="header-anchor" href="#_10-维护检验准则" aria-label="Permalink to &quot;10.维护检验准则&quot;">​</a></h4><ul><li><p>添加检验项目（支持添加多个检验项目）</p><p>-检验项目来源于检验项目列表</p><p>-检验项目在品质部质检时起到重要关键</p></li></ul><h4 id="_11-批量导出" tabindex="-1">11.批量导出 <a class="header-anchor" href="#_11-批量导出" aria-label="Permalink to &quot;11.批量导出&quot;">​</a></h4><ul><li><p>点击导出按钮分为两种导出样式</p><p>-先勾选需导出的内容，点击导出按钮选择第一个选项</p><p>-点击导出按钮，选择第二个选项，手动输入导入1~N条</p></li></ul><h4 id="_12-备注" tabindex="-1">12.备注 <a class="header-anchor" href="#_12-备注" aria-label="Permalink to &quot;12.备注&quot;">​</a></h4><ul><li>点击对应的备注字段添加备注</li></ul><p><img src="'+o+'" alt="如图所示"></p><h4 id="_13-导入" tabindex="-1">13.导入 <a class="header-anchor" href="#_13-导入" aria-label="Permalink to &quot;13.导入&quot;">​</a></h4><ul><li><p>点击批量导入，先下载模板（注意下载的模板只适用于批量导入部件里面上传的模板)</p></li><li><p>点开下载的模板进行编辑（编辑时请阅读表格上面的提示文案，以防导入时出现错误，从而无法导入）</p><p>-模板中的图纸号就是文件库管理列表中所保存的文件号</p><p>-模板中的检验项目名称就是技术部检验项目列表中所添加的检验项</p></li><li><p>点击或者拖拽所保存的模板（只有在部件的批量导入中下载的模板才能上传，其他无效）进行上传</p></li><li><p>上传成功会弹出显示上传的数据，可选择性导入或者一键导入（如果无法导入，请滑动到页面最后，查看提示信息，可能存在编辑时出现的错误，需重新更改再次上传）</p></li></ul><h4 id="_14-更新" tabindex="-1">14.更新 <a class="header-anchor" href="#_14-更新" aria-label="Permalink to &quot;14.更新&quot;">​</a></h4><ul><li>将导出的产品编辑完成后，点击更新按钮上传文件即可</li></ul><p><img src="'+h+'" alt="如图所示"></p><h4 id="_15-工艺路线" tabindex="-1">15.工艺路线 <a class="header-anchor" href="#_15-工艺路线" aria-label="Permalink to &quot;15.工艺路线&quot;">​</a></h4><ul><li>可查看这个部件所使用的工艺路线详情</li></ul><h4 id="_16-工艺路线中工序删除" tabindex="-1">16.工艺路线中工序删除 <a class="header-anchor" href="#_16-工艺路线中工序删除" aria-label="Permalink to &quot;16.工艺路线中工序删除&quot;">​</a></h4><ul><li>部件已维护工艺路线，当其内工序删除时，部件列表中工艺路线名以红色字体显示</li></ul><h4 id="_17-bom表" tabindex="-1">17.BOM表 <a class="header-anchor" href="#_17-bom表" aria-label="Permalink to &quot;17.BOM表&quot;">​</a></h4><ul><li>点击查看这个部件下所用到的物料明细</li></ul><h4 id="_18-详情" tabindex="-1">18.详情 <a class="header-anchor" href="#_18-详情" aria-label="Permalink to &quot;18.详情&quot;">​</a></h4><ul><li>点击查看部件的详细信息</li></ul><p><img src="'+s+'" alt="如图所示"></p><h4 id="_19-维护路线" tabindex="-1">19.维护路线 <a class="header-anchor" href="#_19-维护路线" aria-label="Permalink to &quot;19.维护路线&quot;">​</a></h4><ul><li><p>变更记录：进入维护路线界面，点击“更改记录”按键 弹窗出现操作记录详情，以文字形式记录以下操作（包含操作人、操作时间、操作）</p><p>-会记录以下更改 部件编号修改，部件名称修改，部件规格修改，工艺路线修改，部件状态修改，配套物料修改，物料工序修改</p></li><li><p>点击可添加工艺路线，支持设置默认路线，可在路线中直接更换别的部件去维护路线（当前部件系列下的所有部件）</p></li><li><p>启用/停用：停用时无法使用该路线，启用时可以使用该路线</p></li><li><p>删除：点击可删除此条工艺路线</p></li><li><p>点击工艺路线中的工序标签可查看当前工序绑定物料以及工序详情</p></li><li><p>已添加的工艺路线可点击路线标签中的删除图标进行删除</p></li></ul><h4 id="_20-导入" tabindex="-1">20.导入 <a class="header-anchor" href="#_20-导入" aria-label="Permalink to &quot;20.导入&quot;">​</a></h4><p>1.导入配套物料</p><ul><li><p>点击图标，先下载模板（注意下载的模板只适用于部件配套物料里面上传的模板)</p></li><li><p>点开下载的模板进行编辑（编辑时请阅读表格上面的提示文案，以防导入时出现错误，从而无法导入）</p></li><li><p>点击或者拖拽所保存的模板（只有在部件配套物料导入中下载的模板才能上传，其他无效）进行上传</p></li><li><p>上传成功会弹出显示上传的数据，可选择性导入或者一键导入（如果无法导入，请滑动到页面最后，查看提示信息，可能存在编辑时出现的错误，需从新更改再次上传）</p></li></ul><p>2.手动添加配套物料</p><ul><li><p>点击添加配套物料按钮可新增配套物料，或使用快捷键（键盘向下按键添加配套物料，键盘向上按键删除配套物料）</p></li><li><p>添加的配套物料支持删除</p></li><li><p>选择物料的分类（产品，部件，零件，原料，其他)，物料名称(物料下拉列表会去除已停用的物料)，规格，配套数量，单位，工序号</p></li></ul><p><img src="'+n+'" alt="如图所示"></p><h4 id="_21-添加配套物料" tabindex="-1">21.添加配套物料 <a class="header-anchor" href="#_21-添加配套物料" aria-label="Permalink to &quot;21.添加配套物料&quot;">​</a></h4><ul><li><p>可在查找物料中进行查找</p><p>-在查找物料中点击勾选需要使用的物料会导入下方已勾选物料中，输入配套物料点击确认提交即可</p></li></ul><p><img src="'+u+'" alt="如图所示"></p>',54)])])}const P=l(d,[["render",c]]);export{x as __pageData,P as default};
